  ('48670c28-3ff0-5690-8ee5-64933b18d44a', null, (select id from public.skills where slug = 'write-g9-argument-writing'), null, 'easy',
   $q$Which sentence should be removed because it distracts from the argument?$q$, $q$[{"text":"sentence (2)","is_correct":false,"misconception_token":"removes-key-evidence"},{"text":"sentence (6)","is_correct":false,"misconception_token":"removes-key-evidence"},{"text":"sentence (7)","is_correct":true},{"text":"sentence (9)","is_correct":false,"misconception_token":"removes-concession"}]$q$::jsonb, $q$sentence (7)$q$, $q$Sentence (7) lists apple colors, which says nothing about why the orchard should be saved. Sentence (6) is strong evidence that the trees have scientific value, so it should stay.$q$, 'draft', 'c02e7959-c79e-51f0-b3d8-c97d30e469cc')
