  ('9c9aac1e-3d35-5508-afa0-9c1553379a7d', null, (select id from public.skills where slug = 'write-g10-capitalization-punctuation'), null, 'hard',
   $q$Read the sentence: "The rock climbers trained for months on the indoor wall ___ the real cliff still surprised them with its loose ledges." Which choice correctly fills the blank?$q$, $q$[{"text":"; although","is_correct":false,"misconception_token":"semicolon-before-subordinator"},{"text":"; nonetheless,","is_correct":true},{"text":"; even though,","is_correct":false,"misconception_token":"semicolon-before-subordinator"},{"text":", nonetheless,","is_correct":false,"misconception_token":"comma-splice-with-adverb"}]$q$::jsonb, $q$; nonetheless,$q$, $q$"Nonetheless" is a conjunctive adverb, so it can follow a semicolon that joins two independent clauses. "Although" and "even though" are subordinating conjunctions, which turn the second part into a dependent clause that cannot follow a semicolon.$q$, 'draft', null)
