values
  ('23d60f5e-470c-5882-a58a-74e940a8cce4', null, (select id from public.skills where slug = 'write-g10-grammar-usage'), null, 'hard',
   $q$Read the sentences: "The bakery's oven broke on Friday morning. The bakery still filled every order." Which choice combines them with a clause that shows the correct relationship?$q$, $q$[{"text":"The bakery's oven broke on Friday morning, so the bakery still filled every order.","is_correct":false,"misconception_token":"shows-result-not-contrast"},{"text":"The bakery, whose oven broke on Friday morning, so it still filled every order.","is_correct":false,"misconception_token":"sentence-fragment"},{"text":"Even though its oven broke on Friday morning, the bakery still filled every order.","is_correct":true},{"text":"Because its oven broke on Friday morning, the bakery still filled every order.","is_correct":false,"misconception_token":"shows-cause-not-contrast"}]$q$::jsonb, $q$Even though its oven broke on Friday morning, the bakery still filled every order.$q$, $q$The broken oven made filling orders harder, so the ideas contrast, and "Even though" signals that contrast. "Because" wrongly claims the broken oven caused the bakery to fill every order.$q$, 'draft', null)
