  ('a1a80e57-518e-5428-9179-792195dc6302', null, (select id from public.skills where slug = 'write-g10-grammar-usage'), null, 'hard',
   $q$Which sentence is written correctly and contains an absolute phrase?$q$, $q$[{"text":"The cyclists coasted back to the starting tent, the race was over.","is_correct":false,"misconception_token":"comma-splice"},{"text":"The race over, the cyclists coasted back to the starting tent.","is_correct":true},{"text":"Over the race, the cyclists coasted back to the starting tent.","is_correct":false,"misconception_token":"prepositional-not-absolute"},{"text":"Finished with the race, the starting tent welcomed the cyclists.","is_correct":false,"misconception_token":"dangling-modifier"}]$q$::jsonb, $q$The race over, the cyclists coasted back to the starting tent.$q$, $q$"The race over" is an absolute phrase: a noun with a modifier and no complete verb, adding a detail to the whole sentence. The choice "The cyclists coasted back to the starting tent, the race was over" has a full clause, "the race was over," joined with only a comma, which is a comma splice.$q$, 'draft', null)
