  ('a4076144-8e4e-5452-a05d-4f13a8ef401b', null, (select id from public.skills where slug = 'write-g10-grammar-usage'), null, 'hard',
   $q$Read the sentence: "The goal of the exchange program is not to turn students into tourists but ___." Which choice completes the sentence with parallel structure?$q$, $q$[{"text":"to help them understand daily life in another country","is_correct":true},{"text":"that they understand daily life in another country","is_correct":false,"misconception_token":"clause-breaks-parallel"},{"text":"students should understand daily life in another country","is_correct":false,"misconception_token":"clause-breaks-parallel"},{"text":"helping them understand daily life in another country","is_correct":false,"misconception_token":"gerund-breaks-parallel"}]$q$::jsonb, $q$to help them understand daily life in another country$q$, $q$"Not" is followed by the infinitive phrase "to turn students into tourists," so "but" must be followed by a matching infinitive phrase: "to help them understand." "Helping them understand" has a similar meaning but switches to a gerund.$q$, 'draft', null)
